package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class EmployeeSeparationServiceImpl implements EmployeeSeparationService{private final EmployeeSeparationRepository repo; private final EmployeeRepository er; public EmployeeSeparationServiceImpl(EmployeeSeparationRepository r,EmployeeRepository e){repo=r;er=e;} private boolean mg(String r){return Set.of("ADMIN","HR","MANAGER").contains(r);} public List<EmployeeSeparation> list(String u,boolean m){return m?repo.findAllByOrderByUpdatedAtDesc():repo.findByUserId(u).map(List::of).orElse(List.of());} public EmployeeSeparation create(EmployeeSeparation x,String u){Employee e=er.findByRegisterEmployee_UserId(u).orElseThrow(()->new IllegalArgumentException("Employee not found")); if(repo.findByEmployee_Id(e.getId()).isPresent())throw new IllegalArgumentException("A separation request already exists for this employee"); x.setId(null);x.setEmployee(e);x.setEmployeeName(e.getFullName());x.setUserId(u);x.setStatus("SUBMITTED");x.setManagerCleared(false);x.setHrCleared(false);x.setFinanceCleared(false);x.setAssetCleared(false);x.setAccessCleared(false);return repo.save(x);} public EmployeeSeparation update(Long id,EmployeeSeparation x,String u,boolean m){EmployeeSeparation o=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Request not found"));if(!m&&!u.equals(o.getUserId()))throw new IllegalArgumentException("Access denied");if(!m&&!Set.of("SUBMITTED","REJECTED").contains(o.getStatus()))throw new IllegalArgumentException("Only submitted or rejected requests can be edited");o.setReason(x.getReason());o.setResignationDate(x.getResignationDate());o.setLastWorkingDate(x.getLastWorkingDate());o.setNoticeDays(x.getNoticeDays());o.setExitInterviewNotes(x.getExitInterviewNotes());return repo.save(o);} public EmployeeSeparation review(Long id,String status,String comment,EmployeeSeparation p,String u){EmployeeSeparation o=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Request not found"));o.setStatus(status);o.setHrComment(comment);if("APPROVED".equals(status))o.setApprovedDate(LocalDate.now());if("COMPLETED".equals(status))o.setCompletedDate(LocalDate.now());if(p!=null){if(p.getManagerCleared()!=null)o.setManagerCleared(p.getManagerCleared());if(p.getHrCleared()!=null)o.setHrCleared(p.getHrCleared());if(p.getFinanceCleared()!=null)o.setFinanceCleared(p.getFinanceCleared());if(p.getAssetCleared()!=null)o.setAssetCleared(p.getAssetCleared());if(p.getAccessCleared()!=null)o.setAccessCleared(p.getAccessCleared());if(p.getExitInterviewNotes()!=null)o.setExitInterviewNotes(p.getExitInterviewNotes());} if("COMPLETED".equals(status)&&Boolean.TRUE.equals(o.getManagerCleared())&&Boolean.TRUE.equals(o.getHrCleared())&&Boolean.TRUE.equals(o.getFinanceCleared())&&Boolean.TRUE.equals(o.getAssetCleared())&&Boolean.TRUE.equals(o.getAccessCleared())){Employee e=o.getEmployee();if(e.getEmployeeProfile()!=null)e.getEmployeeProfile().setStatus("INACTIVE");} return repo.save(o);}}
